import { Component } from '@angular/core';
import { LoggerService } from './logger.service';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html'
})
export class AppComponent {
  constructor(private logger: LoggerService) {
    this.logger.log('AppComponent initialized!');
  }

  doSomething() {
    this.logger.log('User clicked the button');
  }
}

slides.content:
Using the `private` (or `public`) keyword in the constructor parameter automatically creates and assigns a class property.

```typescript
constructor(private myService: MyService) {}
```

This is equivalent to:
```typescript
private myService: MyService;
constructor(myService: MyService) {
  this.myService = myService;
}
```

Now you can use `this.myService` anywhere in the class.

